using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
public static class ProbeTvVisualCycle02{public static object Main(){if(EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Idle required");var d=UnityEngine.Object.FindFirstObjectByType<Chapter45Director>();if(d==null||d.chapter!=5)throw new Exception("Open ShoeTower required");var h=d.hazards.Single(h=>h.name=="4F falling television");return new{body=h.body.name,children=h.body.GetComponentsInChildren<Transform>(true).Select(t=>new{t.name,t.gameObject.activeSelf,localPosition=t.localPosition.ToString(),localScale=t.localScale.ToString(),material=t.GetComponent<Renderer>()==null?null:t.GetComponent<Renderer>().sharedMaterial.name,colliders=t.GetComponents<Collider>().Length}).ToArray()};}}
